-- Frozen GATE 2027 preparation decomposition. Official syllabus rows remain unchanged.

begin;

create temporary table _prep_manifest_raw (
  parent_code text not null,
  code text primary key,
  name text not null,
  display_order smallint not null,
  existing_official_code text
) on commit drop;


create temporary table _prep_manifest on commit drop as
select raw.parent_code, raw.code, raw.name, raw.display_order, parent.id as parent_id, parent.subject_id
from _prep_manifest_raw raw
join public.topics parent
  on parent.syllabus_version = 'GATE_2027'
 and parent.code = raw.parent_code
 and parent.is_official = true
where raw.existing_official_code is null;

create unique index _prep_manifest_code_key on _prep_manifest (code);

do $$
declare
  expected_prep_topic_count integer;
  existing_manifest_count integer;
  cycle_count integer;
begin
  select count(*) into expected_prep_topic_count from _prep_manifest;
  if expected_prep_topic_count <= 0 then raise exception 'Preparation manifest is empty'; end if;
  if (select count(*) from _prep_manifest_raw) <> expected_prep_topic_count + (select count(*) from _prep_manifest_raw where existing_official_code is not null) then
    raise exception 'Preparation manifest accounting failed';
  end if;
  if exists (
    select 1 from _prep_manifest_raw raw
    left join public.topics official on official.syllabus_version = 'GATE_2027' and official.code = raw.existing_official_code and official.is_official = true
    left join public.topics parent on parent.syllabus_version = 'GATE_2027' and parent.code = raw.parent_code and parent.is_official = true
    where raw.existing_official_code is not null
      and (official.id is null or parent.id is null or official.subject_id <> parent.subject_id
        or regexp_replace(lower(official.name), '[^a-z0-9]+', '', 'g') <> regexp_replace(lower(raw.name), '[^a-z0-9]+', '', 'g'))
  ) then raise exception 'Excluded official topic does not match the frozen manifest'; end if;
  if (select count(*) from public.subjects where syllabus_version = 'GATE_2027' and is_official = true) <> 11 then raise exception 'Official subject count must remain 11'; end if;
  if (select count(*) from public.topics where syllabus_version = 'GATE_2027' and is_official = true) <> 173 then raise exception 'Official topic count must remain 173'; end if;
  if (select count(*) from _prep_manifest) <> (select count(*) from _prep_manifest_raw where existing_official_code is null) then raise exception 'An official parent code is unresolved'; end if;
  if (select count(distinct code) from _prep_manifest_raw) <> (select count(*) from _prep_manifest_raw) then raise exception 'Preparation manifest codes are duplicated'; end if;

  select count(*) into existing_manifest_count
  from public.topics topic join _prep_manifest manifest on manifest.code = topic.code
  where topic.syllabus_version = 'GATE_2027';

  if existing_manifest_count = 0 then
    select subject_id, parent_id, code, 'GATE_2027', name, display_order, false, null, 'NOT_STARTED'
    from _prep_manifest order by parent_code, display_order, code;
  elsif existing_manifest_count = expected_prep_topic_count then
    if exists (
      select 1 from public.topics topic join _prep_manifest manifest on manifest.code = topic.code
      where topic.syllabus_version is distinct from 'GATE_2027'
         or topic.name is distinct from manifest.name
         or topic.parent_topic_id is distinct from manifest.parent_id
         or topic.subject_id is distinct from manifest.subject_id
         or topic.is_official is distinct from false
         or topic.display_order is distinct from manifest.display_order
         or topic.official_source_text is not null
    ) then raise exception 'Existing preparation rows do not match the frozen manifest'; end if;
  else
    raise exception 'Partial preparation manifest detected: % of % rows', existing_manifest_count, expected_prep_topic_count;
  end if;

  if (select count(*) from public.topics where syllabus_version = 'GATE_2027' and is_official = false) <> expected_prep_topic_count then raise exception 'Unexpected preparation topic count'; end if;
  if exists (select 1 from public.topics where syllabus_version = 'GATE_2027' and is_official = false and (parent_topic_id is null or official_source_text is not null)) then raise exception 'Preparation topic root/source invariant failed'; end if;
  if exists (
    select 1 from public.topics child join public.topics parent on parent.id = child.parent_topic_id
    where child.syllabus_version = 'GATE_2027' and (child.subject_id <> parent.subject_id or child.syllabus_version <> parent.syllabus_version)
  ) then raise exception 'Cross-subject or cross-version hierarchy detected'; end if;
  if exists (select code from public.topics group by syllabus_version, code having count(*) > 1) then raise exception 'Duplicate topic code detected'; end if;

  with recursive ancestry as (
    select id as origin_id, id as current_id, parent_topic_id, array[id] as path, false as cycle
    from public.topics where syllabus_version = 'GATE_2027'
    union all
    select ancestry.origin_id, parent.id, parent.parent_topic_id, ancestry.path || parent.id, parent.id = any(ancestry.path)
    from ancestry join public.topics parent on parent.id = ancestry.parent_topic_id
    where ancestry.parent_topic_id is not null and not ancestry.cycle
  )
  select count(*) into cycle_count from ancestry where cycle;
  if cycle_count <> 0 then raise exception 'Syllabus hierarchy cycle detected'; end if;
end
$$;

commit;
